create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, filename text not null, document_type text not null check (document_type in ('pdf','ppt','pptx')), page_count integer, storage_path text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.document_versions (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, created_by uuid not null references auth.users(id), source_path text not null, created_at timestamptz not null default now());
create table public.annotations (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, page_number integer not null check (page_number > 0), schema_version integer not null default 1, annotation jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.annotation_versions (id uuid primary key default gen_random_uuid(), annotation_id uuid not null references public.annotations(id) on delete cascade, annotation jsonb not null, created_at timestamptz not null default now());
create table public.upload_sessions (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, token_hash text not null unique, status text not null default 'open' check (status in ('open','uploaded','expired','closed')), expires_at timestamptz not null, document_id uuid references public.documents(id), created_at timestamptz not null default now());
create table public.exports (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, owner_id uuid not null references auth.users(id), storage_path text not null, created_at timestamptz not null default now());
create table public.presentation_sessions (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), document_id uuid references public.documents(id), current_page integer not null default 1, expires_at timestamptz not null, created_at timestamptz not null default now());
create table public.remote_events (id bigint generated always as identity primary key, session_id uuid not null references public.presentation_sessions(id) on delete cascade, event jsonb not null, created_at timestamptz not null default now());
create index documents_owner_updated_idx on public.documents(owner_id, updated_at desc); create index annotations_document_page_idx on public.annotations(document_id,page_number); create index remote_events_session_created_idx on public.remote_events(session_id,created_at);
alter table public.profiles enable row level security; alter table public.documents enable row level security; alter table public.document_versions enable row level security; alter table public.annotations enable row level security; alter table public.annotation_versions enable row level security; alter table public.upload_sessions enable row level security; alter table public.exports enable row level security; alter table public.presentation_sessions enable row level security; alter table public.remote_events enable row level security;
create policy "profile owner" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "document owner" on public.documents for all using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy "document version owner" on public.document_versions for all using (exists(select 1 from public.documents d where d.id=document_id and d.owner_id=auth.uid())) with check (exists(select 1 from public.documents d where d.id=document_id and d.owner_id=auth.uid()));
create policy "annotation owner" on public.annotations for all using (exists(select 1 from public.documents d where d.id=document_id and d.owner_id=auth.uid())) with check (exists(select 1 from public.documents d where d.id=document_id and d.owner_id=auth.uid()));
create policy "annotation version owner" on public.annotation_versions for all using (exists(select 1 from public.annotations a join public.documents d on d.id=a.document_id where a.id=annotation_id and d.owner_id=auth.uid())) with check (exists(select 1 from public.annotations a join public.documents d on d.id=a.document_id where a.id=annotation_id and d.owner_id=auth.uid()));
create policy "upload session owner" on public.upload_sessions for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "export owner" on public.exports for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "presentation owner" on public.presentation_sessions for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "remote event owner" on public.remote_events for all using (exists(select 1 from public.presentation_sessions s where s.id=session_id and s.owner_id=auth.uid())) with check (exists(select 1 from public.presentation_sessions s where s.id=session_id and s.owner_id=auth.uid()));
insert into storage.buckets(id,name,public) values ('documents','documents',false),('exports','exports',false),('assets','assets',false) on conflict do nothing;
create policy "private object access" on storage.objects for all using (bucket_id in ('documents','exports','assets') and owner_id=(select auth.uid()::text)) with check (bucket_id in ('documents','exports','assets') and owner_id=(select auth.uid()::text));
